window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6762a927f413417e"]={"versions": [{"id": "FIG-6762a927f413417e", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) der AUTOSAR Classic Platform Bibliothek <strong>CRC Routines</strong> gemäß Anforderung <code>CRC022</code>. Es zeigt die Abhängigkeiten und Inklusionsbeziehungen der C-Quelldateien und Header-Dateien des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Datei-Entitäten und gerichtete Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>Crc_xxx.c</code>: Implementierungsquelldatei(en) des CRC-Moduls (wobei <code>xxx</code> für die jeweilige CRC-Routine bzw. CRC-Algorithmus-Variante steht).\n</li><li><code>Crc.h</code>: Zentraler Modul-Header, der von <code>Crc_xxx.c</code> inkludiert wird.\n</li><li><code>Crc_Cfg.h</code>: Konfigurations-Header des CRC-Moduls, der von <code>Crc.h</code> inkludiert wird.\n</li><li><code>MemMap.h</code>: AUTOSAR-Speicherzuordnungs-Header, der von <code>Crc_Cfg.h</code> inkludiert wird.\n</li></ul>\n<p class=\"fig-p\">Gerichtete Kanten mit der Beschriftung <code>includes</code> definieren die lineare Kette: <code>Crc_xxx.c</code> → <code>Crc.h</code> → <code>Crc_Cfg.h</code> → <code>MemMap.h</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Compile-Time-Ablauf der Header-Inklusion über den C-Präprozessor:</p>\n<ol class=\"fig-list\"><li><code>Crc_xxx.c</code> bindet <code>Crc.h</code> ein.\n</li><li><code>Crc.h</code> bindet <code>Crc_Cfg.h</code> ein, wodurch Konfigurationsparameter und Typdefinitionen vor den Funktionsdeklarationen bereitgestellt werden.\n</li><li><code>Crc_Cfg.h</code> bindet <code>MemMap.h</code> zur Speichersektionszuordnung ein.\n</li></ol>\n<p class=\"fig-p\">Die Kette stellt sicher, dass über die Inklusion von <code>Crc.h</code> in der Quelldatei transitiv alle benötigten Definitionen und Speicherkonfigurationen verfügbar sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Moduldateistruktur (<code>CRC022</code>):</p>\n<ul class=\"fig-list\"><li>Implementierungsdateien <code>Crc_xxx.c</code> dürfen nicht abweichend strukturiert werden und müssen der vorgegebenen Kaskade folgen.\n</li><li>Externe Verwender (z. B. BSW-Module oder SWCs) binden typischerweise <code>Crc.h</code> ein.\n</li><li><code>MemMap.h</code> muss am Ende der Inklusionskette von <code>Crc_Cfg.h</code> bereitgestellt werden, um konsistentes Pragma-/Memory-Mapping für Konstanten, Tabellen und Code zu gewährleisten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f3efc5a662ff5262", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) der AUTOSAR Classic Platform Bibliothek <strong>CRC Routines</strong> gemäß Anforderung <code>CRC022</code>. Es zeigt die Abhängigkeiten und Inklusionsbeziehungen der C-Quelldateien und Header-Dateien des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier Datei-Entitäten und gerichtete Abhängigkeiten (<code>includes</code>):</p>\n<ul class=\"fig-list\"><li><code>Crc_xxx.c</code>: Implementierungsquelldatei(en) des CRC-Moduls (wobei <code>xxx</code> für die jeweilige CRC-Routine bzw. CRC-Algorithmus-Variante steht).\n</li><li><code>Crc.h</code>: Zentraler Modul-Header, der von <code>Crc_xxx.c</code> inkludiert wird.\n</li><li><code>Crc_Cfg.h</code>: Konfigurations-Header des CRC-Moduls, der von <code>Crc.h</code> inkludiert wird.\n</li><li><code>MemMap.h</code>: AUTOSAR-Speicherzuordnungs-Header, der von <code>Crc_Cfg.h</code> inkludiert wird.\n</li></ul>\n<p class=\"fig-p\">Gerichtete Kanten mit der Beschriftung <code>includes</code> definieren die lineare Kette: <code>Crc_xxx.c</code> → <code>Crc.h</code> → <code>Crc_Cfg.h</code> → <code>MemMap.h</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Compile-Time-Ablauf der Header-Inklusion über den C-Präprozessor:</p>\n<ol class=\"fig-list\"><li><code>Crc_xxx.c</code> bindet <code>Crc.h</code> ein.\n</li><li><code>Crc.h</code> bindet <code>Crc_Cfg.h</code> ein, wodurch Konfigurationsparameter und Typdefinitionen vor den Funktionsdeklarationen bereitgestellt werden.\n</li><li><code>Crc_Cfg.h</code> bindet <code>MemMap.h</code> zur Speichersektionszuordnung ein.\n</li></ol>\n<p class=\"fig-p\">Die Kette stellt sicher, dass über die Inklusion von <code>Crc.h</code> in der Quelldatei transitiv alle benötigten Definitionen und Speicherkonfigurationen verfügbar sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Moduldateistruktur (<code>CRC022</code>):</p>\n<ul class=\"fig-list\"><li>Implementierungsdateien <code>Crc_xxx.c</code> dürfen nicht abweichend strukturiert werden und müssen der vorgegebenen Kaskade folgen.\n</li><li>Externe Verwender (z. B. BSW-Module oder SWCs) binden typischerweise <code>Crc.h</code> ein.\n</li><li><code>MemMap.h</code> muss am Ende der Inklusionskette von <code>Crc_Cfg.h</code> bereitgestellt werden, um konsistentes Pragma-/Memory-Mapping für Konstanten, Tabellen und Code zu gewährleisten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6762a927f413417e", "to": "FIG-f3efc5a662ff5262", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
